using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "McpHttpServer", Version = "1.0.0" };
    })
    .WithTools<MyTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo", Title = "Echo Tool")]
    [System.ComponentModel.Description("Echoes the input message back to the caller.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add", Title = "Add Numbers")]
    [System.ComponentModel.Description("Adds two numbers and returns the result.")]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    [System.ComponentModel.Description("Returns current application configuration data.")]
    public static string GetAppSettings() =>
        """
        {
          "environment": "production",
          "featureFlags": { "darkMode": true, "betaFeatures": false },
          "maxRetries": 3,
          "timeoutSeconds": 30
        }
        """;

    [McpServerResource(UriTemplate = "config://app/version", Name = "app-version",
        Title = "Application Version", MimeType = "text/plain")]
    [System.ComponentModel.Description("Returns the current application version.")]
    public static string GetVersion() => "1.0.0";
}

